//! 1000 组配对测试：现有手写基准与带保护上限的本地修正。
use std::{cmp::Ordering,fs};use anyhow::{Result,ensure};
use umasim::{bench::{self,GameOutcome},game::{InheritInfo,ramen::rules::calc_ramen_pt_gain},gamedata::init_global_with_config,output::decision_log::{DecisionLog,DecisionLogRow},trainer::{LocalRamenTrainer,LoggingTrainer,RamenHandwrittenTrainer},utils::{get_workspace_root,load_game_config}};
const RUNS:usize=1000;const BASE_SEED:u64=61444;const UMA:u32=102601;const DECK:[u32;6]=[302424,302894,303044,302924,303024,303054];const INHERIT:InheritInfo=InheritInfo{blue_count:[15,0,0,0,3],extra_count:[10,10,20,20,20,40]};
fn metrics(o:&mut GameOutcome,r:&[DecisionLogRow])->Result<()>{let mut y=[0_i32;3];let mut p=0;for x in r{if x.stage!="RamenSelect"||!x.action_desc.starts_with("吃面/"){continue}let i=if x.turn<24{0}else if x.turn<48{1}else{2};p+=calc_ramen_pt_gain(i,y[i])?;y[i]+=1}let e=y.iter().sum();ensure!(e>0,"seed={}无吃面",o.seed);o.scenario_pt=p;o.eat_count=e;Ok(())}
fn cmp(a:i32,b:i32)->String{match a.cmp(&b){Ordering::Less=>format!("A比B少{}分",b-a),Ordering::Greater=>format!("B比A少{}分",a-b),Ordering::Equal=>"A与B同分".into()}}
fn summary(n:&str,v:&[GameOutcome]){let s=bench::summarize(&v.iter().map(|x|x.score as f64).collect::<Vec<_>>());println!("RESULT {n}: 局数={} 平均评分={:.0} 中位评分={:.0} 最低评分={:.0} 最高评分={:.0}",v.len(),s.mean,s.median,s.min,s.max)}
fn clean(s:&str)->String{s.replace(['\t','\n','\r']," ")}
fn main()->Result<()>{let root=get_workspace_root()?;std::env::set_current_dir(root)?;init_global_with_config(&load_game_config()?)?;println!("A=master 现有手写基准；B=现有基准+受限本地修正（最多牺牲120点基础训练分）。");println!("开始 A/B：每套策略 {RUNS} 局，随机种子 {BASE_SEED}..{}",BASE_SEED+RUNS as u64-1);let(mut av,mut bv,mut aa,mut bb)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());let mut d=String::from("seed\tfinal_comparison\tturn\tstage\tA_action\tB_action\tA_breakdown\tB_breakdown\n");for i in 0..RUNS{let seed=BASE_SEED+i as u64;let ta=LoggingTrainer::new(RamenHandwrittenTrainer::new(),seed);let tb=LoggingTrainer::new(LocalRamenTrainer::new(),seed);let mut a=bench::run_seeded(UMA,&DECK,&INHERIT,seed,&ta)?;let mut b=bench::run_seeded(UMA,&DECK,&INHERIT,seed,&tb)?;let al=ta.take_records();let bl=tb.take_records();metrics(&mut a,&al.rows)?;metrics(&mut b,&bl.rows)?;let c=cmp(a.score,b.score);if let Some((x,y))=al.rows.iter().zip(&bl.rows).find(|(x,y)|x.turn!=y.turn||x.stage!=y.stage||x.action_desc!=y.action_desc){d.push_str(&format!("{seed}\t{c}\t{}\t{}\t{}\t{}\t{}\t{}\n",x.turn,clean(&x.stage),clean(&x.action_desc),clean(&y.action_desc),clean(x.score_breakdown.as_deref().unwrap_or("")),clean(y.score_breakdown.as_deref().unwrap_or(""))))}else{d.push_str(&format!("{seed}\t{c}\t-\t无分歧\t-\t-\t-\t-\n"))}println!("seed={seed} | A[评分={}] | B[评分={}] | {c}",a.score,b.score);aa.extend(al.rows);bb.extend(bl.rows);av.push(a);bv.push(b)}fs::create_dir_all("logs")?;DecisionLog{rows:aa}.save_to(std::path::Path::new("logs/A_existing_decisions.csv"))?;DecisionLog{rows:bb}.save_to(std::path::Path::new("logs/B_local_decisions.csv"))?;fs::write("logs/first_divergence.tsv",d)?;summary("A(master 现有手写基准)",&av);summary("B(现有基准+受限本地修正)",&bv);let ds=av.iter().zip(&bv).map(|(a,b)|b.score-a.score).collect::<Vec<_>>();let aw=ds.iter().filter(|&&x|x<0).count();let bw=ds.iter().filter(|&&x|x>0).count();println!("PAIRED B胜={bw}局 A胜={aw}局 同分={}局",RUNS-aw-bw);let m=ds.iter().sum::<i32>()as f64/RUNS as f64;println!("DELTA 平均评分比较：{}",cmp(0,m.round()as i32));Ok(())}
